// Lightweight animated demonstrations use the game's own renderers and original artwork.
const previewScenes=new WeakMap();let previewFrame=0,previewLastPaint=0;
function previewGame(mode,courseId){const hero=ensureAvatar(),map=courseMap(mode,courseId||selectedCourse(mode)),g={w:1000,h:650,hero,map,x:500,y:500,elapsed:0,moving:true,invincible:0,zaps:0,shieldCharge:0,shieldMax:0,walls:[],mode:selectedMode()},a=makeMiniState(g,mode);g.alt=a;a.level=playerLevel();a.seed=271828;a.energy=1;a.camera=0;a.objects=[];a.shots=[];a.progress=0;
 if(mode==='arena'){g.walls=arenaLayout(g);g.previewField=paintField(g)}
 if(mode==='rally'){g.y=500;a.goal=12500;a.distance=0}
 if(mode==='leap'){a.platforms=[{x:0,y:530,w:260},{x:340,y:475,w:195,gem:true},{x:610,y:405,w:195,drone:true},{x:880,y:480,w:225,gem:true}];a.goal=960;g.y=500}
 if(mode==='tower'){a.path=[[20,150],[270,150],[270,430],[650,430],[650,220],[980,220]];a.slots=[{x:90,y:330},{x:390,y:200},{x:520,y:310},{x:750,y:480}];a.towers=[{x:390,y:200,level:2},{x:520,y:310,level:1}];a.selected=-1;a.funds=85;g.x=930;g.y=325}
 if(mode==='dodge')g.y=400;
 if(mode==='space')g.y=510;
 if(mode==='maze')makeRelicMaze(g);
 if(mode==='memory'){a.pairs=8;a.cols=4;a.rows=4;a.goal=8;a.cards=Array.from({length:16},(_,index)=>({symbol:index%8,index,matched:false}));a.preview=0;a.flipped=[]}
 applyCourseGeometry(g,true);return g}
function renderGamePreview(canvas,t=0){let g=previewScenes.get(canvas);const mode=canvas.dataset.gamePreview;if(!g||g.alt.type!==mode||g.map.id!==(canvas.dataset.coursePreview||selectedCourse(mode))){g=previewGame(mode,canvas.dataset.coursePreview);previewScenes.set(canvas,g)}const a=g.alt,c=canvas.getContext('2d');if(!c)return;g.elapsed=t;a.clock=t;g.hero=ensureAvatar();c.save();c.scale(canvas.width/1000,canvas.height/650);c.clearRect(0,0,1000,650);
 if(mode==='arena'){c.drawImage(g.previewField,0,0);g.x=430+Math.sin(t)*40;g.y=390;for(let i=0;i<3;i++)drawBot(c,{x:250+i*250+Math.sin(t+i)*18,y:190+(i%2)*120,hp:5,maxHp:7,type:i===1?'tank':'blaster',r:23,spawnShield:0,flash:0,fire:.8,dashClock:1},g);if(!drawBreedAvatar(c,g))drawSimplePetPlayer(c,g);const k=(t*1.5)%1;miniGem(c,g.x+(740-g.x)*k,g.y+(190-g.y)*k,'#d5fa59',7)}
 if(mode==='rally'){a.distance=t*190;g.x=roadCentre(g,a.distance)+Math.sin(t*.8)*55;a.objects=Array.from({length:5},(_,i)=>{const d=a.distance+((i*170+t*170)%850)-100;return{d,x:roadCentre(g,d)+(i%2?105:-95),y:g.y-(d-a.distance),kind:i%3===0?'crystal':'cone'}});drawRally(c,g)}
 if(mode==='leap'){g.x=200+(t*80)%650;g.y=450-Math.abs(Math.sin(t*2))*110;a.camera=Math.max(0,g.x-280);drawLeap(c,g)}
 if(mode==='tower'){a.objects=Array.from({length:4},(_,i)=>{const path=a.path,k=Math.floor(t*.2+i)%(path.length-1),p=path[k],q=path[k+1],f=(t*.2+i)%1;return{x:p[0]+(q[0]-p[0])*f,y:p[1]+(q[1]-p[1])*f,hp:4+i,maxHp:9}});a.shots=[{x:520,y:310,tx:a.objects[2].x,ty:430}];drawTower(c,g)}
 if(mode==='dodge'){g.x=500+Math.sin(t)*110;a.objects=[{kind:'warning',x:340,y:360,age:t%1.7,r:65},{kind:'warning',x:720,y:230,age:(t+.7)%1.7,r:58},...Array.from({length:4},(_,i)=>({kind:'meteor',x:180+i*210+Math.sin(t+i)*25,y:(i*170+t*120)%750-50,dx:15,dy:150}))];drawDodge(c,g)}
 if(mode==='space'){g.x=500+Math.sin(t)*90;a.objects=Array.from({length:3},(_,i)=>({x:(g.map.baseIndex===2?380+i*115:g.map.baseIndex===4?120+i*380:210+i*290)+Math.sin(t+i)*45,y:140+i%2*90,hp:4,maxHp:5}));a.shots=Array.from({length:5},(_,i)=>({x:g.x+(i%2?12:-12),y:500-((t*280+i*110)%520),dx:0,dy:-500,colour:weaponFor().colour}));drawSpace(c,g)}
 if(mode==='maze'){a.hint=3;drawMaze(c,g)}
 if(mode==='memory'){a.preview=t%7<1?1:0;a.flipped=t%6<3?[0,a.pairs]:[2,a.pairs+2];drawMemory(c,g)}
 c.restore()}
function gameModeCards(){return `<section class="game-library"><div class="section-title"><div><h2>Eight ways to play. One curious mind.</h2><p>The original Quest Clash Arena is first. Watch a preview, then choose your next adventure.</p></div><span class="count">8 ORIGINAL GAMES</span></div><div class="game-grid">${GAME_MODES.map(m=>`<article class="game-card ${selectedGame().id===m.id?'selected':''}" style="--game-colour:${m.colour}"><button class="game-preview-tile" data-preview-game="${m.id}" aria-label="Preview ${m.name}"><canvas width="400" height="260" data-game-preview="${m.id}" aria-label="Animated ${m.name} gameplay preview"></canvas><span class="preview-play-icon">▶ Preview</span></button><small>${m.id==='arena'?'ORIGINAL GAME · LIVE CO-OP + SOLO':m.tag}</small><h3>${m.name} ${selectedGame().id===m.id?'✓':''}</h3><p>${m.desc}</p><div class="mission-card-line">Stage ${missionStage(m.id)} / 100 · ${missionSummary(m.id)}</div><div class="game-card-options"><button class="preview-text" data-preview-game="${m.id}">Watch preview</button><button class="choose-game-btn" data-game="${m.id}" aria-pressed="${selectedGame().id===m.id}">${selectedGame().id===m.id?'Selected ✓':'Choose game'}</button></div></article>`).join('')}</div></section>`}
function openGamePreview(id){const m=GAME_MODES.find(m=>m.id===id);if(!m)return;openModal(`${topModal(m.id==='arena'?'THE ORIGINAL QUEST CLASH GAME':'GAMEPLAY PREVIEW')}<h2 id="modal-title">${m.name}</h2><p class="sub">${m.desc}</p><div class="large-game-preview"><canvas width="800" height="520" data-game-preview="${m.id}" aria-label="Animated ${m.name} demonstration"></canvas><span>ANIMATED DEMONSTRATION · YOUR RUN STARTS AFTER THE WARM-UP</span></div><div class="preview-instructions"><h3>How to play</h3><p>${m.help}</p><p><b>${m.id==='arena'?'Solo or live cooperative play with 2–4 friends.':'Solo adventure.'}</b> Answer ten questions to earn your starting life, then play. Choose your course and challenge on the home screen.</p></div><div class="modal-actions"><button class="primary" data-preview-start="${m.id}">Choose & start warm-up →</button>${m.id==='arena'?'<button class="secondary" data-live="hub">Play live with friends →</button>':''}<button class="secondary" data-action="close">Back to games</button></div>`);queueGamePreviews()}
function visiblePreviewCanvases(){const all=[...document.querySelectorAll('canvas[data-game-preview]')];return all.filter(canvas=>{const dialog=canvas.closest('dialog');if(modal.open&&!dialog)return false;if(dialog&&!dialog.open)return false;const r=canvas.getBoundingClientRect();return r.bottom>0&&r.top<(window.innerHeight||900)&&r.right>0&&r.left<(window.innerWidth||1400)})}
function paintPreviewFrame(now){previewFrame=0;if(document.hidden)return;const canvases=visiblePreviewCanvases();if(!canvases.length)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;if(now-previewLastPaint>=90||reduced){previewLastPaint=now;for(const canvas of canvases)renderGamePreview(canvas,reduced?1:now/1000)}if(!reduced)previewFrame=requestAnimationFrame(paintPreviewFrame)}
function queueGamePreviews(){if(!previewFrame&&!document.hidden)previewFrame=requestAnimationFrame(paintPreviewFrame)}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.previewGame){event.preventDefault();event.stopImmediatePropagation();openGamePreview(button.dataset.previewGame)}if(button.dataset.previewStart){event.preventDefault();event.stopImmediatePropagation();profile.gameType=button.dataset.previewStart;save();closeModal();navigate('home');chooseBattleTopics()}},true);
window.addEventListener('scroll',queueGamePreviews,{passive:true});window.addEventListener('resize',queueGamePreviews);document.addEventListener('visibilitychange',queueGamePreviews);
if(typeof window.MutationObserver==='function'){const observer=new window.MutationObserver(queueGamePreviews);observer.observe(page,{childList:true});observer.observe(document.querySelector('#modal-content'),{childList:true})}
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');queueGamePreviews();
